import { Component, type ReactNode } from "react";
import { NoData } from "../Placeholder";
import { PlaceholderImage } from "../types";

interface Props {
  children: ReactNode;
  onError?: (error: Error) => void;
  /** Fallback copy; defaults fit the flow canvas, skill callers override. */
  shortLabel?: string;
  longLabel?: string;
}

export class FlowErrorBoundary extends Component<Props, { hasError: boolean }> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error: Error) {
    this.props.onError?.(error);
  }

  render() {
    if (this.state.hasError) {
      return (
        <NoData
          image={PlaceholderImage.NoFlow}
          shortLabel={this.props.shortLabel ?? "Could not render flow"}
          longLabel={this.props.longLabel ?? "An error occurred while visualizing this flow"}
        />
      );
    }
    return this.props.children;
  }
}
